function esc(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function showToastLayer(el){if(typeof el.showPopover==='function'){try{if(el.matches(':popover-open'))el.hidePopover();el.showPopover();return}catch{}}const dialog=$$('dialog[open]').at(-1);if(dialog&&el.parentElement!==dialog)dialog.appendChild(el)}
function hideToastLayer(el){el.classList.remove('show');if(typeof el.hidePopover==='function'){try{if(el.matches(':popover-open'))el.hidePopover()}catch{}}if(el.parentElement!==document.body)document.body.appendChild(el)}
function toast(message){const el=$('#toast');el.textContent=message;showToastLayer(el);requestAnimationFrame(()=>el.classList.add('show'));clearTimeout(toast.timer);const duration=Math.max(3600,Math.min(7000,2200+String(message).length*90));toast.timer=setTimeout(()=>hideToastLayer(el),duration)}
function showDialog(dialog){const node=typeof dialog==='string'?$(dialog):dialog;if(!node||node.open)return;if(typeof node.showModal==='function')node.showModal();else node.setAttribute('open','');const notice=$('#toast');if(notice.classList.contains('show'))showToastLayer(notice)}
function apiErrorMessage(detail,status){if(Array.isArray(detail)){const messages=detail.map(item=>item?.msg||item?.message||'').filter(Boolean);if(messages.length)return messages.join('；')}if(detail&&typeof detail==='object')return detail.message||detail.error||detail.msg||JSON.stringify(detail);return detail||`请求失败（${status}）`}
async function api(url,options={}){const {timeoutMs=35000,signal:externalSignal,...requestOptions}=options,controller=new AbortController(),abort=()=>controller.abort();if(externalSignal)externalSignal.addEventListener('abort',abort,{once:true});const timer=setTimeout(abort,timeoutMs),config={...requestOptions,signal:controller.signal,headers:{'Content-Type':'application/json',...(requestOptions.headers||{})}};try{const res=await fetch(url,config);let body={};try{body=await res.json()}catch{}if(!res.ok)throw new Error(apiErrorMessage(body.detail,res.status));return body}catch(error){if(error.name==='AbortError')throw new Error(externalSignal?.aborted?'搜索已取消':'请求等待超时，请稍后重试');throw error}finally{clearTimeout(timer);if(externalSignal)externalSignal.removeEventListener('abort',abort)}}
function closeDialog(dialog){const node=typeof dialog==='string'?$(dialog):dialog;if(node?.open)node.close()}

async function loadSession(){const data=await api('/api/session');state.admin=data.is_admin;$$('[data-admin]').forEach(el=>el.classList.toggle('hidden',!state.admin));$('#sessionButton').textContent=state.admin?'退出管理员':'管理员登录';if(state.admin)await loadAdminOverview()}
function showPage(name){if(['subscriptions','jobs','accounts','settings'].includes(name)&&!state.admin){showDialog('#loginDialog');return}state.page=name;$$('.page').forEach(el=>el.classList.toggle('active',el.id===`page-${name}`));$$('#mainNav button').forEach(el=>el.classList.toggle('active',el.dataset.page===name));window.scrollTo({top:0,behavior:'smooth'});if(name==='jobs'&&state.admin)renderAdmin();if(name==='settings'&&state.admin)loadSettings()}

async function loadRankings(){const grid=$('#rankingGrid');grid.innerHTML=Array.from({length:12},()=>'<div class="poster-card"><div class="poster-image"></div><h3>正在加载…</h3></div>').join('');const p=new URLSearchParams({media_type:state.rank.type,page:state.rank.page});if(state.rank.year)p.set('year',state.rank.year);if(state.rank.genre)p.set('genre',state.rank.genre);if(state.rank.country)p.set('country',state.rank.country);try{const data=await api(`/api/rankings?${p}`);$('#rankingMessage').textContent=data.message;grid.innerHTML=data.items.length?data.items.map(posterCard).join(''):'<div class="empty-state">管理员配置 TMDB API 密钥后，这里会展示实时排行，不使用虚构演示数据。</div>';if(state.rank.page===1&&data.items.length){const curated=data.items.filter(i=>i.backdrop&&/[\u3400-\u9fff]/.test(i.title||'')&&i.overview&&i.overview!=='暂无简介'&&i.overview.length>=12);state.heroItems=(curated.length?curated:data.items.filter(i=>i.backdrop&&i.overview&&i.overview!=='暂无简介')).slice(0,8);state.heroIndex=0;applyHero()}renderPager(data)}catch(e){grid.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}
function applyHero(){const items=state.heroItems;if(!items.length)return;const item=items[state.heroIndex%items.length];$('#hero').style.backgroundImage=`linear-gradient(90deg,rgba(0,13,8,.94),rgba(0,18,11,.52),rgba(0,18,11,.12)),url("${item.backdrop}")`;$('#heroEyebrow').textContent=`${item.media_type==='movie'?'电影':'剧集'} · 当前热门`;$('#heroTitle').textContent=item.title;$('#heroOverview').textContent=item.overview;$('#heroMeta').innerHTML=`<span>${esc(item.year||'待定')}</span><span>TMDB ${item.score||'-'}</span>`;$('#heroSearch').textContent='搜索这部影视';$('#heroSearch').dataset.query=item.title;$('#heroDots').innerHTML=items.map((_,i)=>`<button data-hero="${i}" class="${i===state.heroIndex?'active':''}" aria-label="第 ${i+1} 部"></button>`).join('')}
function posterCard(item){const age=item.date?(Date.now()-new Date(item.date).getTime())/86400000:9999,newFilm=age>=0&&age<=120;return `<article class="poster-card" data-media='${esc(JSON.stringify(item))}'><div class="poster-image">${item.poster?`<img src="${esc(item.poster)}" alt="${esc(item.title)}" loading="lazy">`:''}${newFilm?'<span class="new-badge">新片</span>':`<span class="rank">#${item.rank||'-'}</span>`}<span class="score">★ ${item.score||'-'}</span></div><h3 title="${esc(item.title)}">${esc(item.title)}</h3><p>${esc(item.year||'待定')} · ${item.media_type==='movie'?'电影':'剧集'}</p></article>`}
function renderPager(data){const el=$('#rankingPager');if(!data.total_pages){el.innerHTML='';return}const page=data.page,total=data.total_pages;const pages=[1,page-1,page,page+1,total].filter((v,i,a)=>v>=1&&v<=total&&a.indexOf(v)===i).sort((a,b)=>a-b);let html=`<button data-rank-page="${page-1}" ${page<=1?'disabled':''}>上一页</button>`;let last=0;for(const p of pages){if(last&&p-last>1)html+='<span>…</span>';html+=`<button data-rank-page="${p}" class="${p===page?'active':''}">${p}</button>`;last=p}html+=`<button data-rank-page="${page+1}" ${page>=total?'disabled':''}>下一页</button><span class="muted">共 ${data.total_results} 部</span>`;el.innerHTML=html}

async function runSearch(query,media=null){query=query.trim();if(!query)return;state.searchController?.abort();const requestId=++state.searchRequestId,controller=new AbortController();state.searchController=controller;showPage('search');state.searchQuery=query;$('#searchInput').value=query;$('#topSearchInput').value=query;$('#searchSummary').classList.add('hidden');$('#mediaMatches').innerHTML='';$('#resourceList').innerHTML='<div class="empty-state"><strong>正在搜索资源…</strong><p>正在连接 PanSou；检测网站超时也会保留未判失效的结果，最长等待约 35 秒。</p></div>';$('#resourceFilters').classList.add('hidden');const params=new URLSearchParams({q:query});if(media?.id){params.set('tmdb_id',media.id);params.set('media_type',media.media_type)}try{const data=await api(`/api/search?${params}`,{timeoutMs:38000,signal:controller.signal});if(requestId!==state.searchRequestId)return;state.resources=data.resources.map((item,index)=>({...item,_order:index}));state.media=data.media||[];state.selectedMedia=data.selected_media||null;state.filter='all';state.inspections.clear();state.inspectionProgress={done:0,total:state.resources.filter(r=>r.provider!=='magnet'&&r.provider!=='115').length};$('#searchSummary').classList.remove('hidden');$('#searchSummary').innerHTML=`<strong>${state.selectedMedia?`当前版本：${esc(state.selectedMedia.title)}（${esc(state.selectedMedia.year||'年份待定')}）`:'搜索完成'}</strong><span>发现 ${data.found} · 显示 ${data.resources.length} · 隐藏明确失效 ${data.hidden_invalid}</span><span id="inspectionProgress" class="inspection-progress">正在检查 0/${state.inspectionProgress.total}</span>`;renderMedia(state.media);renderResources();if(data.warning)toast(data.warning);hydrateInspections()}catch(e){if(requestId!==state.searchRequestId)return;$('#resourceList').innerHTML=`<div class="empty-state search-error"><strong>搜索没有完成</strong><p>${esc(e.message)}</p><button class="primary" data-retry-search>重新搜索</button></div>`;toast(`搜索失败：${e.message}`)}finally{if(requestId===state.searchRequestId)state.searchController=null}}
function renderMedia(items){$('#mediaMatches').innerHTML=(items||[]).slice(0,8).map(item=>`<article class="media-match ${state.selectedMedia?.id===item.id&&state.selectedMedia?.media_type===item.media_type?'selected':''}" data-media='${esc(JSON.stringify(item))}'>${item.poster?`<img src="${esc(item.poster)}" alt="">`:''}<div><span class="chip">${item.media_type==='movie'?'电影':'剧集'} · ${esc(item.year||'')}</span><h3>${esc(item.title)}</h3><p>${esc(item.overview)}</p><button class="select-media" data-select-media="${esc(item.media_type)}:${item.id}">${state.selectedMedia?.id===item.id?'已选版本':'按此版本筛选'}</button></div></article>`).join('')}
function resourceRank(r){const inspection=state.inspections.get(r.fingerprint),playable=inspection?.files?.some(f=>!f.is_dir&&f.browser?.playable),actualEpisode=inspection?.episode_progress?.latest_episode||0;return (playable?1000:0)+(r.validation_state==='valid'?250:0)+(r.match_score||0)*3+actualEpisode}
function renderResources(){const filtered=state.resources.filter(r=>state.filter==='all'||r.provider===state.filter),checking=state.inspectionProgress.done<state.inspectionProgress.total;if(checking)filtered.sort((a,b)=>(a._order||0)-(b._order||0));else filtered.sort((a,b)=>resourceRank(b)-resourceRank(a));const strong=filtered.filter(r=>(r.match_score??100)>=30),weak=filtered.filter(r=>(r.match_score??100)<30),ordered=[...strong,...weak],list=$('#resourceList');$('#resourceFilters').classList.toggle('hidden',!state.resources.length);$('#resourceCount').textContent=`共 ${filtered.length} 条 · 已去重`;$$('#resourceFilters [data-provider]').forEach(b=>b.classList.toggle('active',b.dataset.provider===state.filter));$$('#resourceFilters [data-resource-view]').forEach(b=>b.classList.toggle('active',b.dataset.resourceView===state.resourceView));list.classList.toggle('resource-grid',state.resourceView==='grid');list.classList.toggle('resource-list-view',state.resourceView==='list');if(!ordered.length){list.innerHTML='<div class="empty-state">这个网盘没有可展示的资源。</div>';return}list.innerHTML=strong.map(resourceCard).join('')+(weak.length?`<div class="resource-divider">其他可能相关资源（${weak.length}）</div>${weak.map(resourceCard).join('')}`:'')}
function normalizedTitle(value){return String(value||'').replace(/<[^>]+>/g,'').replace(/\.(mp4|m4v|webm|mov|mkv)$/i,'').toLowerCase().match(/[0-9a-z\u3400-\u9fff]+/g)?.join('')||''}
function requestTitle(resource){let value=String(resource?.media?.title||resource?.title||'影视资源').replace(/\s+/g,' ').trim();for(const marker of [' 名称：','描述：','链接：','🔗','🏷 标签：']){const index=value.indexOf(marker);if(index>0)value=value.slice(0,index).trim()}return(value||'影视资源').slice(0,300)}
function inspectionMatchesTitle(r,inspection){const expected=normalizedTitle(r.media?.title||r.title);if(expected.length<2)return true;return[inspection?.title,...(inspection?.files||[]).map(f=>f.path||f.name)].some(value=>normalizedTitle(value).includes(expected))}
function inspectionMatchesMediaShape(r,inspection){const count=(inspection?.files||[]).filter(f=>!f.is_dir&&f.browser?.playable).length;return!(r.media?.media_type==='movie'&&count>3)}
function isSeriesResource(r){return r.media?.media_type==='tv'||Boolean(r.episode)||/(?:S\d+E\d+|第\s*\d+\s*集|更新至?\s*\d+)/i.test(r.title||'')}
function actualProgressChip(r,inspection){
  if(!isSeriesResource(r))return'';
  if(!inspection)return`<span class="chip actual-progress pending">${r.provider==='magnet'?'实际集数待检查':'正在读取实际集数'}</span>`;
  if(inspection.error)return'<span class="chip actual-progress pending">实际集数暂不可读</span>';
  const progress=inspection.episode_progress||{};
  if(progress.latest_episode)return`<span class="chip actual-progress" title="根据分享目录中的真实视频文件统计">${esc(progress.label)}</span>`;
  if(progress.video_file_count)return`<span class="chip actual-progress" title="文件名没有可靠的集数编号">实际读取 ${progress.video_file_count} 个视频文件</span>`;
  return'<span class="chip actual-progress pending">未读取到视频文件</span>';
}
function resourceCard(r){
  const inspection=state.inspections.get(r.fingerprint),isMagnet=r.provider==='magnet';
  const checking=!isMagnet&&!inspection;
  const playable=inspection?.files?.some(f=>!f.is_dir&&f.browser?.playable);
  const titleMismatch=!isMagnet&&playable&&!inspectionMatchesTitle(r,inspection);
  const typeMismatch=!isMagnet&&playable&&!inspectionMatchesMediaShape(r,inspection);
  const poster=r.poster?`<img class="resource-poster" src="${esc(r.poster)}" alt="">`:`<div class="resource-poster resource-placeholder">${esc(providerMeta[r.provider]?.short||'盘')}</div>`;
  let status='暂时无法判断',statusClass='unknown';
  if(checking){status='检查中';statusClass='checking'}
  else if(isMagnet&&!inspection){status='点击检查磁力文件';statusClass='unknown'}
  else if(inspection?.error){status='授权或读取异常';statusClass='error'}
  else if(playable){status='可以播放';statusClass='ready'}
  else if(inspection){status='不适合网页播放';statusClass='blocked'}
  let inspectState=checking?'正在读取目录和视频格式…':status;
  if(titleMismatch)inspectState='可播放；片名可能不一致，请自行确认';
  else if(typeMismatch)inspectState='可播放；集数形态可能不一致，请自行确认';
  else if(playable)inspectState=`${inspection.episode_progress?.label?`${inspection.episode_progress.label} · `:''}已找到 ${inspection.playable_count} 个可播放文件`;
  const playAction=playable?'<button class="play" data-action="play">播放</button>':isMagnet&&!inspection?'<button class="play" data-action="inspect-magnet">检查播放</button>':isMagnet&&inspection?.error?'<button data-action="inspect-magnet">重新检查</button>':'';
  const match=r.match_score!=null?`<span class="chip match">匹配 ${r.match_score}</span>`:'';
  return `<article class="resource-card" data-id="${esc(r.fingerprint)}"><div class="resource-cover">${poster}<span class="resource-badge">${esc(r.provider_label)}</span><span class="resource-source">${esc(r.source)}</span></div><div class="resource-body"><h3 title="${esc(r.title)}">${esc(r.title)}</h3><div class="chips">${r.quality&&r.quality!=='格式待检查'?`<span class="chip">${esc(r.quality)}</span>`:''}${actualProgressChip(r,inspection)}<span class="chip">${r.validation_state==='valid'?'检测有效':'未判失效'}</span>${match}<span class="chip state-${statusClass}">${status}</span></div><span class="inspect-state" title="${esc(inspectState)}">${esc(inspectState)}</span></div><div class="resource-actions"><button data-action="intro">简介</button><button data-action="copy">复制</button>${playAction}${state.admin&&!isMagnet?'<button class="save" data-action="save">同盘保存</button>':''}</div></article>`;
}
function refreshResourceCard(r){const card=$(`.resource-card[data-id="${r.fingerprint}"]`);if(card)card.outerHTML=resourceCard(r)}
function updateInspectionProgress(){const el=$('#inspectionProgress');if(!el)return;const {done,total}=state.inspectionProgress;el.textContent=done>=total?`格式检查完成 ${total}/${total}`:`正在检查 ${done}/${total}`}
async function hydrateInspections(){const queue=state.resources.filter(r=>r.provider!=='magnet');state.inspectionProgress.total=queue.length;updateInspectionProgress();async function worker(){while(queue.length){const r=queue.shift();try{const result=await api('/api/resources/inspect',{method:'POST',body:JSON.stringify({provider:r.provider,share_url:r.url,extraction_code:r.extraction_code||''})});state.inspections.set(r.fingerprint,result)}catch(e){state.inspections.set(r.fingerprint,{error:e.message,files:[]})}state.inspectionProgress.done++;refreshResourceCard(r);updateInspectionProgress()}}await Promise.all(Array.from({length:Math.min(3,queue.length)},worker));renderResources()}
function resourceByCard(target){const card=target.closest('.resource-card');return state.resources.find(r=>r.fingerprint===card?.dataset.id)}
function countryLabel(value){const names={'United States of America':'美国','United States':'美国','US':'美国','China':'中国大陆','CN':'中国大陆','Hong Kong':'中国香港','HK':'中国香港','Taiwan':'中国台湾','TW':'中国台湾','South Korea':'韩国','KR':'韩国','Japan':'日本','JP':'日本','United Kingdom':'英国','GB':'英国'};return names[value]||value}
function introHtml(item,loading=false){const media=item.media||item,countries=(media.countries||[]).map(countryLabel),genres=media.genres||[],cast=media.cast||[];return `<div class="intro-layout">${media.poster?`<img src="${esc(media.poster)}" alt="${esc(media.title||item.title)}">`:''}<div><p class="eyebrow">${media.media_type==='movie'?'电影':media.media_type==='tv'?'剧集':esc(item.provider_label||'影视详情')}</p><h2>${esc(media.title||item.title)}</h2><div class="intro-meta"><span><b>年份</b>${esc(media.year||'待定')}</span><span><b>国家/地区</b>${esc(countries.join('、')||'待补充')}</span><span><b>类型</b>${esc(genres.join('、')||'待补充')}</span><span class="intro-cast"><b>演员</b>${esc(cast.join('、')||(loading?'正在加载…':'待补充'))}</span></div><h3 class="intro-subtitle">简介</h3><p>${esc(media.overview||item.overview||'暂无简介')}</p>${item.url?`<p class="muted">来源：${esc(item.source)} · ${esc(item.validation_reason||'')}</p>`:''}<div class="intro-actions"><button class="primary" data-intro-search="${esc(media.title||item.title)}">搜索资源</button></div></div></div>`}
async function showIntro(item){const dialog=$('#introDialog'),media=item.media||item;$('#introContent').innerHTML=introHtml(item,Boolean(media.id));showDialog(dialog);if(!media.id||!['movie','tv'].includes(media.media_type))return;try{const details=await api(`/api/media/${media.media_type}/${media.id}`);if(dialog.open)$('#introContent').innerHTML=introHtml({...item,media:details})}catch(e){if(dialog.open){const actor=$('#introContent .intro-cast');if(actor)actor.innerHTML='<b>演员</b>暂时无法加载'}}}
function legacyCopyText(value){const area=document.createElement('textarea');area.value=value;area.setAttribute('readonly','');area.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(area);area.focus();area.select();area.setSelectionRange(0,area.value.length);let copied=false;try{copied=document.execCommand('copy')}finally{area.remove()}return copied}
async function copyText(value){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(value);return true}catch{}}legacyCopyText(value);return false}
function openCopyFallback(value){const dialog=$('#copyDialog'),field=$('#copyValue');field.value=value;$('#systemShare').classList.toggle('hidden',!navigator.share);showDialog(dialog);setTimeout(()=>{field.focus();field.select();field.setSelectionRange(0,field.value.length)},40)}
async function copyLink(r){const value=r.extraction_code?`${r.url} 提取码：${r.extraction_code}`:r.url;try{if(await copyText(value))toast('分享链接已复制');else openCopyFallback(value)}catch(e){openCopyFallback(value)}}
async function inspectMagnetResource(r){toast('正在获取磁力文件列表…');try{const result=await api('/api/magnet/inspect',{method:'POST',body:JSON.stringify({magnet_url:r.url})});state.inspections.set(r.fingerprint,result);renderResources();if(result.playable_count)await playResource(r);else toast('磁力中没有确认适合网页播放的 MP4/H.264/AAC 或 WebM 文件')}catch(e){state.inspections.set(r.fingerprint,{error:e.message,files:[]});renderResources();toast(`磁力检查失败：${e.message}`)}}
function naturalFiles(files){return [...files].sort((a,b)=>a.name.localeCompare(b.name,'zh-CN',{numeric:true,sensitivity:'base'}))}
function playerInfo(r){const media=r.media||r;return `<div>${media.poster?`<img src="${esc(media.poster)}" alt="">`:''}</div><div><p class="eyebrow">${esc(r.provider_label)} · 网页播放</p><h3>${esc(media.title||r.title)}</h3><p>${esc(media.overview||r.overview||'暂无简介')}</p></div>`}
function renderEpisodes(){const player=state.player,files=player?.files||[];$('#episodeCount').textContent=`共 ${files.length} 集/文件`;$('#episodeList').innerHTML=files.map((file,index)=>`<button data-episode-file="${esc(file.id)}" class="${file.id===player.currentId?'active':''}"><b>${String(index+1).padStart(2,'0')}</b><span title="${esc(file.name)}">${esc(file.name)}</span></button>`).join('')}
async function waitForMagnet(player,data,requestId){if(data.state==='ready')return data.play_url;for(let i=0;i<900;i++){if(state.player!==player||requestId!==player.requestId)return'';await new Promise(r=>setTimeout(r,2000));const status=await api(data.status_url);$('#playerStatus').textContent=status.message||'正在从磁力节点获取所选视频…';if(status.state==='ready')return status.play_url;if(status.state==='failed')throw new Error(status.message||'磁力视频准备失败')}throw new Error('磁力视频准备时间过长，请稍后重试')}
function updatePlayProgress(progress,message){const box=$('#playerProgress');box.classList.remove('hidden');box.querySelector('i').style.width=`${Math.max(2,Math.min(100,progress||2))}%`;$('#playerProgressText').textContent=message||'正在准备视频'}
async function waitForCloud(player,data,requestId){if(data.state==='ready')return data.play_url;player.tempId=data.temp_id;$('#cancelPlayPrepare').classList.remove('hidden');for(let i=0;i<900;i++){if(state.player!==player||requestId!==player.requestId)return'';await new Promise(r=>setTimeout(r,1500));const status=await api(data.status_url);updatePlayProgress(status.progress,status.message);$('#playerStatus').textContent=status.message||'正在准备视频…';if(status.state==='ready'){$('#cancelPlayPrepare').classList.add('hidden');return status.play_url}if(['failed','canceled'].includes(status.state))throw new Error(status.message||'视频准备失败')}throw new Error('视频准备时间过长，请稍后重试')}
function destroyHls(player=state.player){if(player?.hls){player.hls.destroy();player.hls=null}}
async function attachPlaySource(player,video,playUrl){destroyHls(player);video.pause();video.removeAttribute('src');video.load();const isHls=playUrl.includes('/api/hls/')||/\.m3u8(?:$|\?)/i.test(playUrl);if(!isHls){video.src=playUrl;video.load();return}if(window.Hls&&Hls.isSupported()){await new Promise((resolve,reject)=>{const hls=new Hls({enableWorker:true,lowLatencyMode:false,startLevel:0,capLevelToPlayerSize:true,backBufferLength:90,maxBufferLength:60});player.hls=hls;player.hlsRecoveryAttempted=false;let settled=false;hls.on(Hls.Events.MEDIA_ATTACHED,()=>hls.loadSource(playUrl));hls.on(Hls.Events.AUDIO_TRACKS_UPDATED,(_,data)=>{const tracks=data.audioTracks||hls.audioTracks||[],preferred=tracks.findIndex(track=>/stereo|2\.0|双声道/i.test(track.name||''));if(preferred>=0)hls.audioTrack=preferred});hls.on(Hls.Events.MANIFEST_PARSED,()=>{if(!settled){settled=true;resolve()}});hls.on(Hls.Events.ERROR,(_,data)=>{if(!data.fatal)return;if(data.type===Hls.ErrorTypes.MEDIA_ERROR&&!player.hlsRecoveryAttempted){player.hlsRecoveryAttempted=true;hls.recoverMediaError();return}const message=data.details||data.type||'HLS 加载失败';if(!settled){settled=true;reject(new Error(message));return}$('#playerStatus').textContent=`视频流加载失败：${message}`;$('#playerStatus').classList.add('show');if(player.alternatives?.length)$('#tryNextSource').classList.remove('hidden')});hls.attachMedia(video)});return}if(video.canPlayType('application/vnd.apple.mpegurl')){video.src=playUrl;video.load();return}throw new Error('当前浏览器不支持 HLS 播放')}
async function selectEpisode(fileId){const player=state.player;if(!player)return;const file=player.files.find(item=>item.id===fileId);if(!file)return;player.currentId=file.id;player.requestId=(player.requestId||0)+1;player.tempId='';const requestId=player.requestId;renderEpisodes();const video=$('#videoPlayer');destroyHls(player);video.pause();video.removeAttribute('src');video.load();$('#playerTitle').textContent=file.name;$('#playerProgress').classList.add('hidden');$('#cancelPlayPrepare').classList.add('hidden');$('#tryNextSource').classList.add('hidden');const isMagnet=player.resource.provider==='magnet';$('#playerSubtitle').textContent=isMagnet?'正在获取磁力视频，完成后自动开始。':'正在同盘准备临时播放，准备完成后自动开始。';$('#playerStatus').textContent=isMagnet?'正在连接磁力节点并准备视频…':'正在保存到网盘临时目录…';$('#playerStatus').classList.add('show');try{let playUrl=player.urls.get(file.id);if(!playUrl){const r=player.resource,title=requestTitle(r),data=isMagnet?await api('/api/magnet/prepare',{method:'POST',body:JSON.stringify({magnet_url:r.url,title,file_id:file.id})}):await api('/api/play/prepare',{method:'POST',body:JSON.stringify({provider:r.provider,share_url:r.url,extraction_code:r.extraction_code||'',title,file_id:file.id})});playUrl=isMagnet?await waitForMagnet(player,data,requestId):await waitForCloud(player,data,requestId);if(playUrl)player.urls.set(file.id,playUrl)}if(!playUrl||requestId!==player.requestId)return;await attachPlaySource(player,video,playUrl);$('#playerProgress').classList.add('hidden');$('#playerStatus').textContent='视频正在加载；若未自动播放，请点击播放键。';await video.play().catch(()=>{});}catch(e){if(requestId!==player.requestId)return;$('#playerStatus').textContent=`播放准备失败：${e.message}`;$('#playerSubtitle').textContent=isMagnet?'可以更换磁力资源或稍后重试。':'可以重试、换一集，或自动尝试下一个来源。';$('#cancelPlayPrepare').classList.add('hidden');if(player.alternatives?.length)$('#tryNextSource').classList.remove('hidden')}}
async function playResource(r){const inspection=state.inspections.get(r.fingerprint),files=naturalFiles((inspection?.files||[]).filter(f=>!f.is_dir&&f.browser?.playable));if(!files.length){toast('这个链接没有确认可网页播放的文件');return}const alternatives=state.resources.filter(x=>x.fingerprint!==r.fingerprint&&state.inspections.get(x.fingerprint)?.files?.some(f=>!f.is_dir&&f.browser?.playable)).sort((a,b)=>resourceRank(b)-resourceRank(a));state.player={resource:r,files,currentId:'',requestId:0,urls:new Map(),alternatives};$('#playerTitle').textContent=r.media?.title||r.title;$('#playerSubtitle').textContent='选择集数开始播放；临时文件在最后一次播放 48 小时后自动删除。';$('#playerMediaInfo').innerHTML=playerInfo(r);$('#playerStatus').textContent='请选择右侧集数';$('#playerStatus').classList.add('show');$('#videoPlayer').removeAttribute('src');$('#videoPlayer').load();renderEpisodes();showDialog('#playDialog');await selectEpisode(files[0].id)}

async function openSave(r){const requestId=++state.saveRequestId;toast('正在读取原始分享内容…');let inspection=state.inspections.get(r.fingerprint);if(!inspection||inspection.error){try{inspection=await api('/api/resources/inspect',{method:'POST',body:JSON.stringify({provider:r.provider,share_url:r.url,extraction_code:r.extraction_code||''})});if(requestId!==state.saveRequestId)return;state.inspections.set(r.fingerprint,inspection)}catch(e){if(requestId===state.saveRequestId)toast(`无法读取分享内容：${e.message}`);return}}if(requestId!==state.saveRequestId)return;state.save={resource:r,inspection};state.directory={id:'',path:'/',crumbs:[]};$('#saveProviderRule').textContent=`将原样保存这条${r.provider_label}分享中的全部内容，只需选择你自己的${r.provider_label}目录。`;renderFileScope();showDialog('#saveDialog');try{await loadDirectories()}catch(e){if(requestId===state.saveRequestId)toast(`无法读取网盘目录：${e.message}`)}}
function videoFiles(){return state.save.inspection.files.filter(f=>!f.is_dir)}
function renderFileScope(){const inspection=state.save.inspection,topLevel=(inspection.files||[]).filter(f=>!f.parent_id||f.parent_id==='0');$('#fileScope').innerHTML=`<div class="save-original-summary"><strong>保存原始分享的全部内容</strong><span>共读取到 ${inspection.files.length} 个文件/目录${topLevel.length?`，其中顶层 ${topLevel.length} 项`:''}；目录结构与文件名称保持不变。</span></div>`}
function chooseScope(scope){const rows=$$('#fileScope input[type=checkbox]'),files=videoFiles();if(scope==='single')rows.forEach((el,i)=>el.checked=i===0);else if(scope==='all')rows.forEach(el=>el.checked=true);else{const first=files.find(f=>f.name.match(/S\d{1,2}E\d+/i));const season=first?.name.match(/S(\d{1,2})E/i)?.[1];rows.forEach((el,i)=>el.checked=season?new RegExp(`S0?${Number(season)}E`,'i').test(files[i].name):true)}}
function formatSize(size){if(!size)return'大小未知';const u=['B','KB','MB','GB','TB'];let i=0,n=Number(size);while(n>=1024&&i<u.length-1){n/=1024;i++}return`${n.toFixed(i>1?1:0)} ${u[i]}`}
async function loadDirectories(){const {resource}=state.save;$('#directoryPath').textContent=state.directory.path;renderBreadcrumbs();$('#directoryList').innerHTML='<div class="empty-state">正在读取目录…</div>';try{const data=await api(`/api/admin/accounts/${resource.provider}/directories`,{method:'POST',body:JSON.stringify({parent_id:state.directory.id,parent_path:state.directory.path})});$('#directoryList').innerHTML=data.items.length?data.items.map(d=>`<button class="directory-item" data-id="${esc(d.id)}" data-name="${esc(d.name)}" data-path="${esc(d.path)}"><span>📁 ${esc(d.name)}</span><span>进入 →</span></button>`).join(''):'<div class="empty-state">这个目录里没有子文件夹，可以直接保存到这里。</div>'}catch(e){$('#directoryList').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}
function renderBreadcrumbs(){const all=[{id:'',path:'/',name:'根目录'},...state.directory.crumbs];$('#directoryBreadcrumbs').innerHTML=all.map((c,i)=>`<button data-crumb="${i}">${esc(c.name)}</button>`).join('')}
async function confirmSave(){const r=state.save.resource,button=$('#confirmSave');button.disabled=true;button.textContent='正在创建保存任务…';try{const job=await api('/api/admin/save',{method:'POST',body:JSON.stringify({provider:r.provider,share_url:r.url,extraction_code:r.extraction_code||'',title:requestTitle(r),target_id:state.directory.id,target_path:state.directory.path,selected_file_ids:[],scope:'all',duplicate_policy:$('#duplicatePolicy').value})});closeDialog('#saveDialog');showPage('jobs');toast(`任务 #${job.id} 已进入任务中心`);await loadAdminOverview()}catch(e){toast(`同盘保存失败：${e.message}`)}finally{button.disabled=false;button.textContent='保存原始全部内容'}}

async function loadAdminOverview(){if(!state.admin)return;try{state.overview=await api('/api/admin/overview');renderAdmin()}catch(e){if(e.message.includes('登录')){state.admin=false;await loadSession()}else toast(e.message)}}
function renderAdmin(){if(!state.overview)return;renderAccounts();renderJobs();renderSubscriptions()}
function renderAccounts(){const el=$('#accountGrid');if(!el)return;el.innerHTML=state.overview.accounts.map(a=>{const m=providerMeta[a.provider],displayState=a.configured?a.state:'disconnected',displayRisk=a.configured?a.risk_status:'unknown';return `<article class="account-card"><div class="account-title"><div class="account-name"><span class="provider-icon ${m.class}">${m.short}</span><div><h2>${m.label}</h2><p>${esc(a.account_label||'尚未授权')}</p></div></div><span class="status ${displayState}">${displayState==='connected'?'已连接':displayState==='error'?'连接异常':'未连接'}</span></div><div class="account-row"><span>授权方式</span><strong>${esc(a.credential_kind||m.method)}</strong></div><div class="account-row"><span>风控/连接状态</span><strong>${displayRisk==='normal'?'正常':displayRisk==='warning'?'需要处理':'待检测'}</strong></div>${a.configured&&a.last_error?`<p class="muted">${esc(a.last_error)}</p>`:''}<div class="account-actions"><button class="ghost" data-account="${a.provider}" data-action="auth">${a.configured?'更新授权':'立即授权'}</button>${a.configured?`<button class="ghost" data-account="${a.provider}" data-action="probe">测试连接</button>`:''}</div></article>`}).join('')}
function readableJobError(error=''){if(error.includes('200025'))return '百度分享缺少转存信息；请更新百度 Cookie（需含 BDUSS/STOKEN），或换一个来源';return error}
function jobItem(j){const label=({queued:'排队中',running:'进行中',success:'已完成',failed:'失败'})[j.status]||j.status,error=readableJobError(j.error||'');return `<article><div><h3>#${j.id} · ${esc(j.title)}</h3><p>${esc(providerMeta[j.provider]?.label||j.provider)} · ${esc(j.stage||j.kind)}${error?` · ${esc(error)}`:''}${j.retry_count?` · 已重试 ${j.retry_count} 次`:''}</p></div><div class="list-actions"><span class="status ${j.status}">${label} · ${j.progress}%</span>${j.status==='failed'?`<button data-job-retry="${j.id}">重试</button>`:''}</div></article>`}
function tempItem(t){const labels={ready:'临时播放',preparing:'准备中',cleanup_pending:'清理中',cleanup_failed:'清理失败',deleted:'已删除',kept:'已转永久',canceled:'已取消',failed:'准备失败'},label=labels[t.state]||t.state,error=t.direct_hint?.cleanup_error||'';return `<article><div><h3>${esc(t.file_name)}</h3><p>${esc(providerMeta[t.provider]?.label||t.provider)} · ${t.state==='ready'?`到期 ${new Date(t.expires_at).toLocaleString()}`:label}${error?` · ${esc(error)}`:''}</p></div><div class="list-actions"><span class="status ${t.state}">${label}</span>${['ready','cleanup_failed'].includes(t.state)?`<button data-temp-cleanup="${esc(t.id)}">${t.state==='ready'?'立即清理':'重新清理'}</button>`:''}</div></article>`}
function renderJobs(){const jobs=$('#jobList'),temps=$('#tempList');if(!jobs||!temps)return;const activeJobs=state.overview.jobs.filter(j=>j.status!=='success'),completedJobs=state.overview.jobs.filter(j=>j.status==='success');jobs.innerHTML=(activeJobs.length?activeJobs.map(jobItem).join(''):'<article><p>当前没有进行中或失败的保存任务。</p></article>')+(completedJobs.length?`<details class="history-group"><summary>已完成任务 ${completedJobs.length} 条</summary><div class="simple-list">${completedJobs.map(jobItem).join('')}</div></details>`:'');const activeTemps=state.overview.temporary.filter(t=>!['deleted','kept'].includes(t.state)),historyTemps=state.overview.temporary.filter(t=>['deleted','kept'].includes(t.state));temps.innerHTML=(activeTemps.length?activeTemps.map(tempItem).join(''):'<article><p>没有待处理的临时播放文件。</p></article>')+(historyTemps.length?`<details class="history-group"><summary>历史已处理 ${historyTemps.length} 条</summary><div class="simple-list">${historyTemps.map(tempItem).join('')}</div></details>`:'')}
function renderSubscriptions(){const el=$('#subscriptionList');if(!el)return;el.innerHTML=state.overview.subscriptions.length?state.overview.subscriptions.map(s=>`<article><div><h3>${esc(s.title)}</h3><p>${s.media_type==='movie'?'电影':s.media_type==='anime'?'动漫':'电视剧'} ${s.year||''}</p></div><button class="ghost" data-subscription-delete="${s.id}">取消追更</button></article>`).join(''):'<article><p>还没有追更作品。</p></article>'}

function openCredential(provider){const m=providerMeta[provider],dialog=$('#credentialDialog');const is115=provider==='115',isQuark=provider==='quark';$('#credentialContent').innerHTML=`<p class="eyebrow">${esc(m.label)}</p><h2>${esc(m.method)}授权</h2><div class="credential-help">${esc(m.help)}</div>${is115?'<button id="start115Qr" class="primary full">115 App 扫码（支付宝小程序端类型）</button><div id="qr115" class="qr-box"></div><div class="credential-help">请使用 115 手机 App 扫码确认；系统会按支付宝小程序端类型登记，减少普通设备名额占用。扫码不可用时，也可在下方粘贴 115 Cookie。</div>':''}${isQuark?'<button id="startQuarkTvQr" class="primary full">绑定夸克电视端播放授权</button><div id="qrQuark" class="qr-box"></div><div class="credential-help">请使用夸克手机 App 扫码并确认。重新扫码会续用这台 NAS 已有的电视设备标识，不会新增一台设备；若账号当前已超限，会自动回退 Cookie，旧设备需在夸克 App 的登录设备管理中清理。</div>':''}<label>${is115?'备用 Cookie':isQuark?'目录与同盘保存 Cookie':'授权凭证'}<textarea id="credentialValue" rows="6" placeholder="凭证只加密保存在本机 NAS"></textarea></label><button id="saveCredential" class="primary full">保存并验证</button>`;dialog.dataset.provider=provider;showDialog(dialog)}
async function saveCredential(){const provider=$('#credentialDialog').dataset.provider,value=$('#credentialValue').value.trim();if(!value){toast('请填写授权凭证');return}try{await api(`/api/admin/accounts/${provider}`,{method:'PUT',body:JSON.stringify({credential:value,kind:provider==='quark'?'cookie':provider==='china_mobile'?'token':'auto',account_label:'已授权账号'})});closeDialog('#credentialDialog');toast('授权成功');await loadAdminOverview()}catch(e){toast(e.message)}}
async function start115(){const box=$('#qr115');box.innerHTML='<p>正在生成二维码…</p>';try{const data=await api('/api/admin/accounts/115/qr/start',{method:'POST'});box.innerHTML=`<img src="${esc(data.qr_image_url)}" alt="115 登录二维码"><p>${esc(data.message)}</p>`;poll115(data.session_id,box)}catch(e){box.innerHTML=`<p>${esc(e.message)}</p>`}}
async function poll115(id,box){for(let i=0;i<40&&$('#credentialDialog').open;i++){await new Promise(r=>setTimeout(r,2200));try{const data=await api(`/api/admin/accounts/115/qr/${id}`);box.querySelector('p').textContent=data.message;if(data.state==='succeeded'){toast('115 授权成功');closeDialog('#credentialDialog');await loadAdminOverview();return}if(['expired','canceled'].includes(data.state))return}catch(e){box.querySelector('p').textContent=e.message;return}}}
async function startQuarkTV(){const box=$('#qrQuark');box.innerHTML='<p>正在生成电视端二维码…</p>';try{const data=await api('/api/admin/accounts/quark/tv/qr/start',{method:'POST'});box.innerHTML=`<img src="${esc(data.qr_image_url)}" alt="夸克电视端登录二维码"><p>${esc(data.message)}</p>`;pollQuarkTV(data.session_id,box)}catch(e){box.innerHTML=`<p>${esc(e.message)}</p>`}}
async function pollQuarkTV(id,box){for(let i=0;i<60&&$('#credentialDialog').open;i++){await new Promise(r=>setTimeout(r,2200));try{const data=await api(`/api/admin/accounts/quark/tv/qr/${id}`);const message=box.querySelector('p');if(message)message.textContent=data.message;if(data.state==='succeeded'){toast('夸克云端转码播放授权成功');closeDialog('#credentialDialog');await loadAdminOverview();return}if(['expired','canceled'].includes(data.state))return}catch(e){const message=box.querySelector('p');if(message)message.textContent=e.message;return}}}

async function loadSettings(){try{const data=await api('/api/admin/integrations');$('#pansouUrl').value=data.pansou_url||'';$('#checkerUrl').value=data.checker_url||'';$('#telegramChatId').value='';$('#tmdbKey').placeholder=data.tmdb_configured?'已配置；留空不修改':'请输入 TMDB API Key';$('#telegramToken').placeholder=data.telegram_configured?'已配置；留空不修改':'请输入 Bot Token';$('#telegramStatus').textContent=data.telegram_configured?'已配置，可发送测试通知':'未配置，保存 Token 和 Chat ID 后生效';$('#adminSessionPolicy').textContent=data.admin_session_policy||'关闭浏览器后需要重新登录';$('#adminPasswordStatus').textContent=data.admin_password_weak?'当前管理员密码较弱；仅建议在可信内网使用，并尽快改为更强密码。':'当前管理员密码强度正常。'}catch(e){toast(e.message)}}

document.addEventListener('click',async e=>{const episode=e.target.closest('[data-episode-file]');if(episode){await selectEpisode(episode.dataset.episodeFile);return}const introSearch=e.target.closest('[data-intro-search]');if(introSearch){const query=introSearch.dataset.introSearch;closeDialog('#introDialog');await runSearch(query);return}const quick=e.target.closest('#quickCategory button');if(quick){state.rank.country=quick.dataset.country||'';state.rank.genre=quick.dataset.genre||'';state.rank.page=1;$('#countryFilter').value=state.rank.country;$('#genreFilter').value=state.rank.genre;$$('#quickCategory button').forEach(b=>b.classList.toggle('active',b===quick));await loadRankings();return}const quickYear=e.target.closest('#quickYear button');if(quickYear){state.rank.year=quickYear.dataset.year||'';state.rank.page=1;$('#yearFilter').value=state.rank.year;$$('#quickYear button').forEach(b=>b.classList.toggle('active',b===quickYear));await loadRankings();return}const hero=e.target.closest('[data-hero]');if(hero){state.heroIndex=Number(hero.dataset.hero);applyHero();return}if(e.target.id==='heroSearch'&&e.target.dataset.query){e.preventDefault();await runSearch(e.target.dataset.query);return}const page=e.target.closest('[data-page]')?.dataset.page;if(page){e.preventDefault();showPage(page);return}const rank=e.target.closest('[data-rank-page]');if(rank&&!rank.disabled){state.rank.page=Number(rank.dataset.rankPage);await loadRankings();return}const filter=e.target.closest('#typeFilter button');if(filter){state.rank.type=filter.dataset.value;state.rank.page=1;$$('#typeFilter button').forEach(b=>b.classList.toggle('active',b===filter));await loadRankings();return}const view=e.target.closest('#resourceFilters [data-resource-view]');if(view){state.resourceView=view.dataset.resourceView;localStorage.setItem('feihai-resource-view',state.resourceView);renderResources();return}const provider=e.target.closest('#resourceFilters [data-provider]');if(provider){state.filter=provider.dataset.provider;renderResources();return}const select=e.target.closest('[data-select-media]');if(select){const [type,id]=select.dataset.selectMedia.split(':');const media=state.media.find(x=>String(x.id)===id&&x.media_type===type);if(media)await runSearch(state.searchQuery,media);return}const poster=e.target.closest('.poster-card,.media-match');if(poster?.dataset.media){showIntro(JSON.parse(poster.dataset.media));return}const action=e.target.closest('[data-action]')?.dataset.action;if(action&&e.target.closest('.resource-card')){const r=resourceByCard(e.target);if(action==='intro')showIntro(r);if(action==='copy')await copyLink(r);if(action==='inspect-magnet')await inspectMagnetResource(r);if(action==='play')await playResource(r);if(action==='save')await openSave(r);return}if(e.target.matches('[data-close]')){if(e.target.closest('#playDialog')){const player=state.player;destroyHls(player);$('#videoPlayer').pause();$('#videoPlayer').removeAttribute('src');$('#videoPlayer').load();state.player=null}closeDialog(e.target.closest('dialog'));return}const scope=e.target.closest('[data-scope]');if(scope){chooseScope(scope.dataset.scope);return}const dir=e.target.closest('.directory-item');if(dir){state.directory.crumbs.push({id:dir.dataset.id,path:dir.dataset.path,name:dir.dataset.name});state.directory.id=dir.dataset.id;state.directory.path=dir.dataset.path;await loadDirectories();return}const crumb=e.target.closest('[data-crumb]');if(crumb){const i=Number(crumb.dataset.crumb);if(i===0){state.directory={id:'',path:'/',crumbs:[]}}else{state.directory.crumbs=state.directory.crumbs.slice(0,i);const c=state.directory.crumbs.at(-1);state.directory.id=c.id;state.directory.path=c.path}await loadDirectories();return}if(e.target.id==='confirmSave'){await confirmSave();return}if(e.target.id==='createFolderButton'){const name=prompt('新文件夹名称');if(name){try{await api(`/api/admin/accounts/${state.save.resource.provider}/folders`,{method:'POST',body:JSON.stringify({parent_id:state.directory.id,parent_path:state.directory.path,name})});await loadDirectories()}catch(err){toast(err.message)}}return}const account=e.target.closest('[data-account]');if(account){if(account.dataset.action==='auth')openCredential(account.dataset.account);else{try{await api(`/api/admin/accounts/${account.dataset.account}/probe`,{method:'POST'});toast('连接正常');await loadAdminOverview()}catch(err){toast(err.message)}}return}if(e.target.id==='saveCredential'){await saveCredential();return}if(e.target.id==='start115Qr'){await start115();return}if(e.target.id==='startQuarkTvQr'){await startQuarkTV();return}const sub=e.target.closest('[data-subscription-delete]');if(sub){await api(`/api/admin/subscriptions/${sub.dataset.subscriptionDelete}`,{method:'DELETE'});await loadAdminOverview();return}});

$('#cancelPlayPrepare').addEventListener('click',async()=>{const player=state.player;if(!player?.tempId)return;player.requestId++;try{await api(`/api/play/status/${player.tempId}`,{method:'DELETE'});updatePlayProgress(0,'已取消播放准备');$('#playerStatus').textContent='播放准备已取消';$('#cancelPlayPrepare').classList.add('hidden')}catch(e){toast(e.message)}});
$('#tryNextSource').addEventListener('click',async()=>{const player=state.player,next=player?.alternatives?.shift();if(!next){toast('没有其他已确认可播放的来源');return}toast(`正在尝试 ${next.provider_label} 的下一个来源`);await playResource(next)});
$('#checkAllAccounts').addEventListener('click',async()=>{const button=$('#checkAllAccounts');button.disabled=true;button.textContent='正在检查…';try{const data=await api('/api/admin/accounts/check-all',{method:'POST'});const failed=data.results.filter(x=>x.state==='error').length;toast(failed?`检查完成，${failed} 个账号需要处理`:'检查完成，已授权账号均正常');await loadAdminOverview()}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='立即检查全部网盘账号'}});
$('#testTelegram').addEventListener('click',async()=>{const button=$('#testTelegram');button.disabled=true;button.textContent='正在发送…';try{const data=await api('/api/admin/integrations/telegram/test',{method:'POST'});toast(data.message||'测试通知已发送')}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='发送测试通知'}});
$('#selectCopyValue').addEventListener('click',()=>{const field=$('#copyValue');field.focus();field.select();field.setSelectionRange(0,field.value.length);legacyCopyText(field.value);toast('链接已选中，请粘贴确认')});
$('#systemShare').addEventListener('click',async()=>{try{await navigator.share({title:'飞海网盘分享链接',text:$('#copyValue').value})}catch(e){if(e.name!=='AbortError')toast('系统分享未完成')}});
$('#jobList').addEventListener('click',async e=>{const button=e.target.closest('[data-job-retry]');if(!button)return;button.disabled=true;button.textContent='正在重试…';try{await api(`/api/admin/jobs/${button.dataset.jobRetry}/retry`,{method:'POST'});toast('任务已重新开始');await loadAdminOverview()}catch(err){toast(err.message)}finally{button.disabled=false}});
$('#tempList').addEventListener('click',async e=>{const button=e.target.closest('[data-temp-cleanup]');if(!button)return;button.disabled=true;button.textContent='正在清理…';try{const data=await api(`/api/admin/temporary/${button.dataset.tempCleanup}/cleanup`,{method:'POST'});toast(data.message||'临时文件已清理');await loadAdminOverview()}catch(err){toast(err.message);await loadAdminOverview()}finally{button.disabled=false}});
$('#saveDialog').addEventListener('close',()=>{state.saveRequestId++});
$('#downloadBackup').addEventListener('click',async()=>{try{const res=await fetch('/api/admin/backup');if(!res.ok)throw new Error('备份下载失败');const blob=await res.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`feihai-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url);toast('备份已下载，请妥善保存')}catch(e){toast(e.message)}});
$('#uploadBackup').addEventListener('click',()=>$('#backupFile').click());
$('#backupFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{toast('正在恢复备份…');const text=await file.text(),data=await api('/api/admin/backup/restore',{method:'POST',body:text});toast(data.message);await loadSettings();await loadAdminOverview()}catch(err){toast(`恢复失败：${err.message}`)}finally{e.target.value=''}});

$('#videoPlayer').addEventListener('loadedmetadata',()=>{$('#playerStatus').classList.remove('show');$('#playerProgress').classList.add('hidden');$('#playerSubtitle').textContent=`正在播放 · ${$('#playerTitle').textContent}`});
$('#videoPlayer').addEventListener('error',()=>{if(state.player?.hls)return;const video=$('#videoPlayer'),code=video.error?.code||0;$('#playerStatus').textContent=`视频加载失败（错误 ${code}）。请换一集，或尝试下一个来源。`;$('#playerStatus').classList.add('show');if(state.player?.alternatives?.length)$('#tryNextSource').classList.remove('hidden')});

$('#sessionButton').addEventListener('click',async()=>{if(state.admin){await api('/api/logout',{method:'POST'});state.admin=false;showPage('home');await loadSession();toast('已退出管理员')}else showDialog('#loginDialog')});
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#loginUsername').value,password:$('#loginPassword').value})});closeDialog('#loginDialog');$('#loginPassword').value='';await loadSession();toast('管理员验证成功')}catch(err){toast(err.message)}});
$('#searchForm').addEventListener('submit',e=>{e.preventDefault();runSearch($('#searchInput').value)});$('#topSearch').addEventListener('submit',e=>{e.preventDefault();runSearch($('#topSearchInput').value)});$('#resourceList').addEventListener('click',e=>{if(e.target.closest('[data-retry-search]'))runSearch(state.searchQuery,state.selectedMedia)});
$('#yearFilter').addEventListener('change',e=>{state.rank.year=e.target.value;state.rank.page=1;loadRankings()});$('#genreFilter').addEventListener('change',e=>{state.rank.genre=e.target.value;state.rank.page=1;loadRankings()});$('#countryFilter').addEventListener('change',e=>{state.rank.country=e.target.value;state.rank.page=1;loadRankings()});
$('#settingsForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/admin/integrations',{method:'PUT',body:JSON.stringify({pansou_url:$('#pansouUrl').value,checker_url:$('#checkerUrl').value,tmdb_api_key:$('#tmdbKey').value,telegram_bot_token:$('#telegramToken').value,telegram_chat_id:$('#telegramChatId').value})});toast('设置已保存');$('#tmdbKey').value='';$('#telegramToken').value='';await loadSettings();await loadRankings()}catch(err){toast(err.message)}});
$('#subscriptionForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/admin/subscriptions',{method:'POST',body:JSON.stringify({title:$('#subscriptionTitle').value,media_type:$('#subscriptionType').value,year:$('#subscriptionYear').value?Number($('#subscriptionYear').value):null})});$('#subscriptionTitle').value='';await loadAdminOverview();toast('已添加追更')}catch(err){toast(err.message)}});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)closeDialog(d)}));
for(let y=new Date().getFullYear()+1;y>=1950;y--){$('#yearFilter').insertAdjacentHTML('beforeend',`<option value="${y}">${y}</option>`)}
Promise.all([loadSession(),loadRankings()]).catch(e=>toast(e.message));
setInterval(()=>{if(state.page==='home'&&state.heroItems.length>1){state.heroIndex=(state.heroIndex+1)%state.heroItems.length;applyHero()}},8000);
setInterval(()=>{if(state.admin&&state.page==='jobs')loadAdminOverview()},3000);
